#!/usr/bin/env python3
"""Original SH-2 runtime ECC/retry diagnostic. MIT: adjacent LICENSE.

ST-162 §8.2.1 CDC_CdInit and §§4.2/4.3: guest code observes RETRY/ERROR,
uses invalid ERROR fields per §7.2.4(4), compares no-ECC error output with corrected data, and escapes infinite retry
by playing a good sector. The test supplies original two-sector raw media.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_cd_drive import command
from build_scu import assembler

HERE = Path(__file__).resolve().parent
BASE = 0x0600A000


def build():
    def cmd(words, name, offset):
        return command(words, name, BASE + offset)

    def wait_status(name, offset, status):
        return (f'{name}:\n' + cmd([0, 0, 0, 0], name + '_command', offset)
                + f'load {BASE + offset:#x},r1\nmov.l @r1,r0\n'
                + f'load {status:#x},r2\ncmp/eq r2,r0\nbt {name}_done\nbra {name}\nnop\n{name}_done:\n')

    def wait_count(name, offset):
        return (f'{name}:\n' + cmd([0x5100, 0, 0, 0], name + '_command', offset)
                + f'tst #255,r0\nbf {name}_done\nbra {name}\nnop\n{name}_done:\n')

    def get(name, offset, result):
        return (cmd([0x6300, 0, 0, 1], name, offset)
                + f'load 0x25818000,r1\nmov.l @r1,r0\n'
                + f'load {BASE + result:#x},r1\nmov.l r0,@r1\n'
                + cmd([0x0600, 0, 0, 0], name + '_end', offset + 0x10))

    s = cmd([0x0400, 0xFFFF, 0, 0x8002], 'initialize_retry', 0)
    s += cmd([0x3000, 0, 0, 0], 'connect', 0x10)
    s += cmd([0x1080, 150, 0x80, 1], 'play_retry', 0x20)
    s += 'mov #0,r3\nretry:\n' + cmd([0, 0, 0, 0], 'retry_command', 0x30)
    s += f'load {BASE + 0x30:#x},r1\nmov.l @r1,r0\nload 0x09FF,r2\ncmp/eq r2,r0\nbt failed\n'
    s += 'load 0x0880,r2\ncmp/eq r2,r0\nbf retry_again\nadd #1,r3\nretry_again:\nbra retry\nnop\nfailed:\n'
    s += f'load {BASE + 0x18C:#x},r1\nmov.l r3,@r1\n'
    s += cmd([0x5100, 0, 0, 0], 'failed_count', 0x40)
    # Independently retained ECC=80; new error-output policy=40.
    s += cmd([0x0480, 0xFFFF, 0, 0xFF40], 'initialize_output', 0x50)
    s += cmd([0x1080, 150, 0x80, 1], 'play_output', 0x60)
    s += wait_count('output_count', 0x70)
    s += get('output_get', 0x80, 0x180)
    # Two P/Q passes repair the same media in actual guest reads, including
    # the independently constructed two-pass parity graph.
    s += cmd([0x0400, 0xFFFF, 0, 0x0100], 'initialize_correct', 0xA0)
    s += cmd([0x1080, 150, 0x80, 1], 'play_correct', 0xB0)
    s += wait_count('correct_count', 0xC0)
    s += get('correct_get', 0xD0, 0x184)
    s += cmd([0x0400, 0xFFFF, 0, 0x8080], 'initialize_infinite', 0xF0)
    s += cmd([0x1080, 150, 0x80, 1], 'play_infinite', 0x100)
    s += wait_status('infinite', 0x110, 0x0880)
    s += cmd([0x1080, 151, 0x80, 1], 'escape_infinite', 0x120)
    s += wait_count('escape_count', 0x130)
    s += get('escape_get', 0x140, 0x188)
    s += f'load {BASE + 0x190:#x},r1\nload 0x600D,r0\nmov.l r0,@r1\nsleep\n'
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    code = assembler.assemble(s, base=0x200)
    rom[0x200:0x200 + len(code)] = code
    lines = ['# Original runtime CD ECC/retry guest. MIT: adjacent LICENSE.',
             '# Generated by build_cd_decode.py; unspecified bytes are zero.']
    for address in range(0, len(rom), 16):
        block = rom[address:address + 16]
        if any(block):
            lines.append(f'{address:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', block)))
    return '\n'.join(lines) + '\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text, digest = build()
    path = HERE / 'cd-decode.hex'
    if args.check:
        assert path.read_text() == text, 'Rebuild cd-decode.hex'
    else:
        path.write_text(text)
    print(f'{"Verified" if args.check else "Built"} cd-decode.hex; expanded ROM SHA-256 {digest}')
